from app.agent import ask_data_agent

questions = [
    "How many orders are present in the database?",
    "What is the total revenue generated by Maharashtra?",
    "Which five states have the highest revenue?"
]

for question in questions:
    print("\n" + "=" * 60)
    print("QUESTION:", question)

    try:
        result = ask_data_agent(question)
        print("\nANSWER:")
        print(result["answer"])
        print("\nCHART:", result["chart"])

    except Exception as e:
        print("\nERROR:", str(e))